// Run with: node --test .github/scripts/pr-gate.test.js
const test = require('node:test');
const assert = require('node:assert/strict');
const run = require('./pr-gate.js');
const { evaluate, parseBody } = run;

const GOOD_BODY = [
  '- [x] Bug fix',
  'Fixes #100',
  'Before: <img width="100" src="https://github.com/user-attachments/assets/a" />',
  'After: <img width="100" src="https://github.com/user-attachments/assets/b" />',
  '- [x] I ran this change on a real Nightingale instance myself and attached screenshots above.',
].join('\n');

const issue = (over = {}) => ({
  number: 100, isPR: false, author: { login: 'reporter', association: 'NONE' }, labels: [], stateReason: null, ...over,
});

function fakeApi(over = {}) {
  return {
    owner: 'ccfos',
    repo: 'nightingale',
    hasWriteAccess: async (login) => (over.writers || []).includes(login),
    authorPRs: async () => ({ merged: over.merged ?? 0, open: over.open || [] }),
    listFiles: async () => (over.files || ['center/router/router_user.go'])
      .map((f) => (typeof f === 'string' ? { path: f, changes: 10 } : f)),
    getIssue: async (number) => (over.issues || { 100: issue() })[number] || null,
    listCommenters: async (number) => (over.commenters || {})[number] || [],
  };
}

const pr = (over = {}) => ({
  number: 10, author: 'someone', isBot: false, association: 'NONE', labels: [], body: GOOD_BODY, ...over,
});

const labelsOf = async (p, api) => [...new Set((await evaluate(p, api)).problems.map((x) => x.label))];

test('trusted authors and waived PRs are skipped', async () => {
  const empty = { body: '' };
  assert.deepEqual(await labelsOf(pr({ ...empty, isBot: true }), fakeApi()), []);
  assert.deepEqual(await labelsOf(pr({ ...empty, author: 'zbqBaoqing' }), fakeApi()), []);
  assert.deepEqual(await labelsOf(pr({ ...empty, association: 'MEMBER' }), fakeApi()), []);
  assert.deepEqual(await labelsOf(pr(empty), fakeApi({ writers: ['someone'] })), []);
  assert.deepEqual(await labelsOf(pr({ ...empty, labels: ['skip-evidence-check'] }), fakeApi()), []);
});

test('the diff decides the exemption, not the ticked PR type', async () => {
  const docsOnly = fakeApi({ files: ['README.md', 'doc/api/x.md', 'alert/eval/eval_test.go', '.github/workflows/test.yml'] });
  assert.deepEqual(await labelsOf(pr({ body: '' }), docsOnly), []);

  const refactor = pr({ body: '- [x] Refactor / docs / chore / tests (no behavior change)' });
  assert.deepEqual(await labelsOf(refactor, fakeApi({ files: ['README.md', 'alert/eval/eval.go'] })),
    ['needs-issue', 'needs-evidence']);
});

test('a PR without self-testing evidence fails whatever the author history', async () => {
  // Shape of #3477: unticked checklist, "Pending" evidence, issue "N/A".
  const body = '- [x] Bug fix\nWhich issue(s) this PR fixes:\nN/A\nBefore:\nPending: attach a screenshot\n'
    + '- [ ] I ran this change on a real Nightingale instance myself and attached screenshots above';
  const { problems } = await evaluate(pr({ body, association: 'CONTRIBUTOR' }), fakeApi({ merged: 10 }));
  assert.deepEqual(problems.map((p) => p.label), ['needs-issue', 'needs-evidence', 'needs-evidence']);
});

test('evidence hidden in an HTML comment does not count', async () => {
  const body = `<!--\n${GOOD_BODY}\n-->`;
  assert.deepEqual(await labelsOf(pr({ body }), fakeApi({ merged: 10 })), ['needs-issue', 'needs-evidence']);
});

test('only images uploaded through the GitHub web UI count as evidence', async () => {
  const contributor = fakeApi({ merged: 10 });
  const withImages = (...images) => GOOD_BODY.split('\n').filter((l) => !l.includes('<img')).concat(images).join('\n');
  const upload = (id) => `<img src="https://github.com/user-attachments/assets/${id}" />`;

  // Shapes seen in past PRs: images generated by a script and committed to the fork.
  assert.deepEqual(await labelsOf(pr({ body: withImages(
    '![before](https://raw.githubusercontent.com/someone/nightingale/pr-evidence/before.png)',
    '![after](./docs/pr-evidence/3371/after.png)',
    '![badge](https://img.shields.io/badge/tests-passing-green)') }), contributor), ['needs-evidence']);

  // A bug fix needs a before and an after; the same upload twice is one image.
  assert.deepEqual(await labelsOf(pr({ body: withImages(upload('a'), upload('a')) }), contributor), ['needs-evidence']);
  assert.deepEqual(await labelsOf(pr({ body: withImages(upload('a'), upload('b')) }), contributor), []);
  const feature = withImages(upload('a')).replace('Bug fix', 'New feature');
  assert.deepEqual(await labelsOf(pr({ body: feature }), contributor), []);
});

test('newcomers can have two open PRs at a time, and the oldest ones survive', async () => {
  const discussed = { issues: { 100: issue({ labels: ['bug'] }) } };
  assert.deepEqual(await labelsOf(pr(), fakeApi({ ...discussed, open: [8, 10] })), []);
  assert.deepEqual(await labelsOf(pr(), fakeApi({ ...discussed, open: [8, 9, 10] })), ['over-limit']);
  assert.deepEqual(await labelsOf(pr(), fakeApi({ ...discussed, open: [10, 11, 12] })), []);
  assert.deepEqual(await labelsOf(pr(), fakeApi({ merged: 3, open: [7, 8, 9, 10] })), []);
});

test('size limits count only files outside docs and tests', async () => {
  const many = (n, changes = 10) => Array.from({ length: n }, (_, i) => ({ path: `pkg/x/f${i}.go`, changes }));
  const tests = Array.from({ length: 100 }, (_, i) => ({ path: `pkg/x/f${i}_test.go`, changes: 500 }));
  const discussed = { issues: { 100: issue({ labels: ['bug'] }) } };

  assert.deepEqual(await labelsOf(pr(), fakeApi({ ...discussed, files: [...many(10, 50), ...tests] })), []);
  assert.deepEqual(await labelsOf(pr(), fakeApi({ ...discussed, files: many(11) })), ['over-limit']);
  assert.deepEqual(await labelsOf(pr(), fakeApi({ ...discussed, files: many(2, 251) })), ['over-limit']);

  assert.deepEqual(await labelsOf(pr(), fakeApi({ merged: 3, files: many(50, 200) })), []);
  assert.deepEqual(await labelsOf(pr(), fakeApi({ merged: 3, files: many(51) })), ['over-limit']);
  assert.deepEqual(await labelsOf(pr(), fakeApi({ merged: 3, files: many(2, 5001) })), ['over-limit']);
});

test('skip-size-limit lifts the size limit and nothing else', async () => {
  const large = Array.from({ length: 30 }, (_, i) => ({ path: `datasource/loki/f${i}.go`, changes: 100 }));
  const waived = { labels: ['skip-size-limit'] };
  const discussed = { issues: { 100: issue({ labels: ['enhancement'] }) } };

  assert.deepEqual(await labelsOf(pr(waived), fakeApi({ ...discussed, files: large })), []);
  assert.deepEqual(await labelsOf(pr(waived), fakeApi({ ...discussed, files: large, open: [7, 8, 10] })), ['over-limit']);
  assert.deepEqual(await labelsOf(pr({ ...waived, body: '' }), fakeApi({ files: large })), ['needs-issue', 'needs-evidence']);
});

test('authors below the merged PR threshold need a maintainer response on the issue', async () => {
  assert.deepEqual(await labelsOf(pr(), fakeApi({ merged: 2 })), ['needs-issue']);
  assert.deepEqual(await labelsOf(pr(), fakeApi({ merged: 3 })), []);
});

test('a maintainer response is a comment, a triage label or a maintainer-authored issue', async () => {
  const commented = fakeApi({ commenters: { 100: [{ login: 'x', association: 'NONE' }, { login: 'lead', association: 'MEMBER' }] } });
  assert.deepEqual(await labelsOf(pr(), commented), []);

  const privateMember = fakeApi({ writers: ['hidden'], commenters: { 100: [{ login: 'hidden', association: 'CONTRIBUTOR' }] } });
  assert.deepEqual(await labelsOf(pr(), privateMember), []);

  assert.deepEqual(await labelsOf(pr(), fakeApi({ issues: { 100: issue({ labels: ['bug'] }) } })), []);
  assert.deepEqual(await labelsOf(pr(), fakeApi({ issues: { 100: issue({ author: { login: 'lead', association: 'OWNER' } }) } })), []);

  const onlyOutsiders = fakeApi({ commenters: { 100: [{ login: 'someone', association: 'NONE' }] } });
  assert.deepEqual(await labelsOf(pr(), onlyOutsiders), ['needs-issue']);
});

test('the linked issue must be a real, non-declined issue of this repository', async () => {
  const contributor = { merged: 10 };
  assert.deepEqual(await labelsOf(pr(), fakeApi({ ...contributor, issues: {} })), ['needs-issue']);
  assert.deepEqual(await labelsOf(pr(), fakeApi({ ...contributor, issues: { 100: issue({ isPR: true }) } })), ['needs-issue']);
  assert.deepEqual(await labelsOf(pr(), fakeApi({ ...contributor, issues: { 100: issue({ labels: ['wontfix'] }) } })), ['needs-issue']);
  assert.deepEqual(await labelsOf(pr(), fakeApi({ ...contributor, issues: { 100: issue({ stateReason: 'not_planned' }) } })), ['needs-issue']);
  assert.deepEqual(await labelsOf(pr(), fakeApi(contributor)), []);
});

test('parseBody reads closing keywords for this repository only', () => {
  const parse = (body) => parseBody(body, 'ccfos', 'nightingale').issues;
  assert.deepEqual(parse('Fixes #12, closes: #13 and Resolves https://github.com/ccfos/nightingale/issues/14'), [12, 13, 14]);
  assert.deepEqual(parse('fixes ccfos/nightingale#15'), [15]);
  assert.deepEqual(parse('Fixes https://github.com/other/repo/issues/1, see #2, Fixes #'), []);
});

// --- side effects ---

function fakeGithub({ comments = [], reopenFails = false } = {}) {
  const calls = [];
  const record = (name, result = {}) => async (params) => { calls.push([name, params]); return { data: result }; };
  const github = {
    calls,
    paginate: async (fn, params, map) => { const res = await fn(params); return map ? map(res) : res.data; },
    graphql: async () => ({ merged: { issueCount: 0 }, open: { nodes: [] } }),
    rest: {
      repos: { getCollaboratorPermissionLevel: async () => ({ data: { permission: 'read' } }) },
      pulls: {
        listFiles: async () => ({ data: [{ filename: 'alert/eval/eval.go', changes: 10 }] }),
        update: async (params) => {
          calls.push(['pulls.update', params]);
          if (reopenFails) throw Object.assign(new Error('cannot reopen'), { status: 422 });
          return { data: {} };
        },
      },
      issues: {
        get: async () => ({ data: { user: { login: 'lead' }, author_association: 'MEMBER', labels: [], state_reason: null } }),
        listComments: async () => ({ data: comments }),
        getLabel: async () => { throw Object.assign(new Error('not found'), { status: 404 }); },
        createLabel: record('createLabel'),
        addLabels: record('addLabels'),
        removeLabel: record('removeLabel'),
        createComment: record('createComment'),
        updateComment: record('updateComment'),
      },
    },
  };
  return github;
}

async function runWith(github, over) {
  const failures = [];
  await run({
    github,
    core: { info() {}, setFailed: (m) => failures.push(m) },
    context: {
      repo: { owner: 'ccfos', repo: 'nightingale' },
      payload: {
        repository: { default_branch: 'main' },
        pull_request: { number: 1, state: 'open', user: { login: 'someone', type: 'User' }, author_association: 'NONE', labels: [], body: GOOD_BODY, ...over },
      },
    },
  });
  return { failures, names: github.calls.map(([name]) => name), find: (name) => github.calls.find(([n]) => n === name)?.[1] };
}

const BOT_CLOSED = { id: 7, body: '<!-- pr-evidence-check -->\nit has been **closed automatically**' };

test('a failing open PR is labeled, commented and closed', async () => {
  const r = await runWith(fakeGithub(), { body: '' });
  assert.deepEqual(r.find('addLabels').labels, ['needs-issue', 'needs-evidence']);
  assert.match(r.find('createComment').body, /closed automatically/);
  assert.equal(r.find('pulls.update').state, 'closed');
  assert.equal(r.failures.length, 1);
});

test('a passing open PR without our labels is left untouched', async () => {
  const r = await runWith(fakeGithub(), {});
  assert.deepEqual(r.names, []);
  assert.deepEqual(r.failures, []);
});

test('a PR closed by the check is reopened once it passes', async () => {
  const r = await runWith(fakeGithub({ comments: [BOT_CLOSED] }), { state: 'closed', labels: [{ name: 'needs-evidence' }] });
  assert.deepEqual(r.names, ['pulls.update', 'removeLabel', 'updateComment']);
  assert.equal(r.find('pulls.update').state, 'open');
  assert.doesNotMatch(r.find('updateComment').body, /closed automatically/);
});

test('the skip label reopens a PR closed by the check', async () => {
  const r = await runWith(fakeGithub({ comments: [BOT_CLOSED] }),
    { state: 'closed', body: '', labels: [{ name: 'needs-issue' }, { name: 'skip-evidence-check' }] });
  assert.equal(r.find('pulls.update').state, 'open');
  assert.equal(r.find('removeLabel').name, 'needs-issue');
});

test('a PR closed by a maintainer is never reopened', async () => {
  const passed = { id: 7, body: '<!-- pr-evidence-check -->\n✅ Check passed' };
  const r = await runWith(fakeGithub({ comments: [passed] }), { state: 'closed' });
  assert.deepEqual(r.names, []);

  const failing = await runWith(fakeGithub({ comments: [passed] }), { state: 'closed', body: '' });
  assert.ok(!failing.names.includes('pulls.update'));
  assert.doesNotMatch(failing.find('updateComment').body, /closed automatically/);
});

test('a reopen that GitHub refuses asks for a new PR instead of failing', async () => {
  const r = await runWith(fakeGithub({ comments: [BOT_CLOSED], reopenFails: true }), { state: 'closed', labels: [{ name: 'needs-evidence' }] });
  assert.match(r.find('updateComment').body, /open a new PR/);
  assert.deepEqual(r.failures, []);
});
